import "core-js/modules/es6.function.name";
import "core-js/modules/web.dom.iterable";
import * as echarts from 'echarts';
import { queryInstanceTodoTaskCount, queryInstanceTodoTaskCountByProcessKey } from '@/api/workflow/analyse/todoTaskAnalysis';
import showListOrEchart from "../../../components/dataPickerTabs/showListOrEchart.vue";
var resizeObserve = null;
export default {
  name: 'TodoTaskAnalysis',
  components: {
    showListOrEchart: showListOrEchart
  },
  props: {},
  data: function data() {
    return {
      isList: false,
      checked: false,
      options: [{
        value: '5',
        label: '前5名'
      }, {
        value: '10',
        label: '前10名'
      }, {
        value: '15',
        label: '前15名'
      }, {
        value: '20',
        label: '前20名'
      }],
      size: '5',
      myChart: null,
      // 环图
      doughnutData: [],
      // 待办任务环图数据
      todoTaskListData: [],
      // 待办任务列表数据
      todoTaskListByKeyData: [],
      // 代办任务下钻列表数据
      copyData: [],
      // 下钻列表数据备份
      listParam: {},
      // 下钻列表参数
      dialogTableVisible: false,
      // 下钻列表是否弹出
      searchContent: '',
      // 搜索内容
      loading: false,
      current: 1,
      pageSize: 10,
      total: 10,
      isGetResult: false,
      // 是否获取到查询结果
      isLoading: false,
      processName: '',
      // 流程名称
      processTaskCount: '' // 待办任务数量
    };
  },
  computed: {
    doughnutOption: function doughnutOption() {
      var self = this;
      var data = [];
      self.doughnutData.forEach(function (item) {
        var obj = {};
        obj.value = item.processTaskCount;
        obj.name = item.processName;
        obj.processKey = item.processKey;
        data.push(obj);
      });
      return {
        color: ['#2794F8', '#FFBB00', '#EE7B4E', '#52C566', '#6F5EF9', '#6DC8EC', '#945FB9', '#FF9845', '#1E9493', '#FF99C3', '#BDD2FD', '#BDD2FD', '#5AD8A6', '#BDEFDB', '#5D7092', '#C2C8D5', '#F6BD16', '#FBE5A2', '#E8684A', '#F6C3B7'],
        tooltip: {
          trigger: 'item',
          borderWidth: 0,
          backgroundColor: 'rgba(111, 111, 111, 1)',
          textStyle: {
            color: '#fff',
            fontWeight: '400'
          },
          confine: true,
          extraCssText: 'white-space: normal; word-break: break-all;'
        },
        legend: {
          type: 'scroll',
          top: '0',
          right: 0,
          icon: 'circle',
          itemWidth: 9,
          itemHeight: 9,
          textStyle: {
            color: '#8C8C8C'
          },
          padding: 0,
          formatter: function formatter(name) {
            return echarts.format.truncateText(name, 100, '12px', '...');
          },
          tooltip: {
            show: false
          }
        },
        series: [{
          type: 'pie',
          radius: ['35%', '55%'],
          minAngle: 3,
          avoidLabelOverlap: true,
          itemStyle: {
            borderColor: '#fff',
            borderWidth: 2
          },
          top: 20,
          label: {
            show: true,
            color: '#545672',
            formatter: '{b}\n{c}个',
            padding: [5, 5, 5, 5],
            lineHeight: 17
          },
          labelLine: {
            show: true,
            length: 40,
            length2: 60,
            lineStyle: {
              width: 1,
              color: '#545672'
            }
          },
          data: data
        }]
      };
    }
  },
  watch: {
    doughnutOption: function doughnutOption() {
      this.drawDoughnut();
    }
  },
  mounted: function mounted() {
    var _this = this;
    this.doughnutDataLoad(this.size);
    this.todoTaskListLoad(this.size);
    resizeObserve = new ResizeObserver(function () {
      if (_this.myChart) _this.myChart.resize();
    });
    resizeObserve.observe(document.getElementById('processOverviewContent'));
  },
  beforeUnmount: function beforeUnmount() {
    resizeObserve.disconnect();
  },
  methods: {
    // 搜索
    searchProcess: function searchProcess(value) {
      var self = this;
      self.loading = true;
      self.pageSize = 10;
      self.current = 1;
      self.todoTaskListByKeyLoad(self.listParam, self.pageSize, self.current, value);
    },
    // 重置
    clearData: function clearData() {
      var self = this;
      self.loading = true;
      self.searchContent = '';
      self.current = 1;
      self.pageSize = 10;
      self.loading = true;
      self.todoTaskListByKeyLoad(self.listParam, self.pageSize, self.current, self.searchContent);
    },
    // 数据下钻打开弹窗
    isDialogTable: function isDialogTable(row, column) {
      var self = this;
      self.searchContent = '';
      self.listParam = {};
      self.total = 0;
      self.todoTaskListByKeyData = [];
      if (column.label !== '流程名称' && column.label !== '序号') {
        self.dialogTableVisible = !self.dialogTableVisible;
      }
      self.listParam = {
        processKey: row.processKey
      };
      self.processName = row.processName;
      self.processTaskCount = row.processTaskCount;
      self.loading = true;
      self.pageSize = 10;
      self.current = 1;
      self.todoTaskListByKeyLoad(self.listParam, self.pageSize, self.current, self.searchContent);
    },
    // 每页显示几条数据
    handleSizeChange: function handleSizeChange(value) {
      var self = this;
      self.pageSize = value;
      self.loading = true;
      self.todoTaskListByKeyLoad(self.listParam, self.pageSize, self.current, self.searchContent);
    },
    // 列表页码切换
    handleCurrentChange: function handleCurrentChange(value) {
      var self = this;
      self.current = value;
      self.loading = true;
      self.todoTaskListByKeyLoad(self.listParam, self.pageSize, self.current, self.searchContent);
    },
    // 查询
    queryType: function queryType(value) {
      var self = this;
      self.isGetResult = false;
      self.todoTaskListLoad(value);
      self.doughnutDataLoad(value);
    },
    // 清除
    clearValue: function clearValue() {
      this.size = '5';
      this.queryType(this.size);
    },
    // 查看列表
    isShowList: function isShowList(value) {
      var self = this;
      self.isList = value;
      self.$nextTick(function () {
        self.drawDoughnut();
      });
    },
    // 绘制环图
    drawDoughnut: function drawDoughnut() {
      var self = this;
      if (self.myChart) {
        self.myChart.dispose();
        self.myChart = null;
      }
      if (!this.$refs.todoTaskCharts || this.$refs.todoTaskCharts.clientWidth === 0) return;
      // 基于准备好的dom，初始化echarts实例
      self.myChart = echarts.init(this.$refs.todoTaskCharts);
      self.myChart.setOption(self.doughnutOption);
      self.myChart.off('click');
      self.myChart.on('click', function (param) {
        self.searchContent = '';
        self.listParam = {};
        self.total = 0;
        self.todoTaskListByKeyData = [];
        self.dialogTableVisible = !self.dialogTableVisible;
        self.listParam = {
          processKey: param.data.processKey
        };
        self.processName = param.data.name;
        self.processTaskCount = param.data.value;
        self.loading = true;
        self.pageSize = 10;
        self.current = 1;
        self.todoTaskListByKeyLoad(self.listParam, self.pageSize, self.current, self.searchContent);
      });
    },
    // 待办任务排行查询
    doughnutDataLoad: function doughnutDataLoad(value) {
      var _this2 = this;
      var self = this;
      var data = {
        size: value
      };
      queryInstanceTodoTaskCount(data).then(function (res) {
        if (res.code === 10000 && res.data && res.data.records.length > 0) {
          self.doughnutData = res.data.records;
          self.isGetResult = false;
          self.$nextTick(function () {
            self.drawDoughnut();
          });
        } else {
          self.doughnutData = [];
          self.isGetResult = true;
        }
      }).catch(function () {
        _this2.$message({
          message: '',
          type: 'error'
        });
      });
    },
    // 待办任务排行查询
    todoTaskListLoad: function todoTaskListLoad(value) {
      var _this3 = this;
      var self = this;
      self.isLoading = true;
      var data = {
        size: value
      };
      queryInstanceTodoTaskCount(data).then(function (res) {
        if (res.code === 10000) {
          self.todoTaskListData = res.data.records;
          self.isLoading = false;
        }
      }).catch(function () {
        _this3.$message({
          message: '数据请求失败',
          type: 'error'
        });
      });
    },
    // 流程下钻到流程名称
    todoTaskListByKeyLoad: function todoTaskListByKeyLoad(value, size, current, keyword) {
      var _this4 = this;
      var self = this;
      var data = {
        current: current,
        // 当前页
        size: size,
        // 每页显示条数
        keyword: keyword,
        processKey: value.processKey
      };
      queryInstanceTodoTaskCountByProcessKey(data).then(function (res) {
        if (res.code === 10000) {
          self.todoTaskListByKeyData = res.data.records;
          self.copyData = res.data.records;
          self.total = res.data.total;
          self.loading = false;
        }
      }).catch(function () {
        _this4.$message({
          message: '数据请求失败',
          type: 'error'
        });
      });
    }
  }
};
